package az.kampus.sim;
import org.springframework.boot.*;
import org.springframework.boot.autoconfigure.*;
import org.springframework.web.bind.annotation.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.*;
import java.util.*;
import java.math.*;
@SpringBootApplication @RestController public class SimApplication {
 @Value("${kampus.sim-key}") String key;
 @Value("${kampus.state-file:.local/vasp-state.json}") String stateFile;
 final com.fasterxml.jackson.databind.ObjectMapper json=new com.fasterxml.jackson.databind.ObjectMapper();
 @jakarta.annotation.PostConstruct void load(){try{var p=java.nio.file.Path.of(stateFile);if(java.nio.file.Files.exists(p)){var root=json.readTree(p.toFile());root.path("balances").fields().forEachRemaining(e->balances.put(e.getKey(),e.getValue().asLong()));root.path("requests").fields().forEachRemaining(e->{@SuppressWarnings("unchecked") Map<String,Object> v=json.convertValue(e.getValue(),Map.class);requests.put(e.getKey(),v);});root.path("orders").fields().forEachRemaining(e->{@SuppressWarnings("unchecked") Map<String,Object> v=json.convertValue(e.getValue(),Map.class);orders.put(e.getKey(),v);});}}catch(Exception e){throw new IllegalStateException("Cannot read mock VASP state",e);}}
 void persist(){try{var path=java.nio.file.Path.of(stateFile).toAbsolutePath();java.nio.file.Files.createDirectories(path.getParent());var temp=path.resolveSibling(path.getFileName()+".tmp");json.writeValue(temp.toFile(),Map.of("balances",balances,"orders",orders,"requests",requests));java.nio.file.Files.move(temp,path,java.nio.file.StandardCopyOption.ATOMIC_MOVE,java.nio.file.StandardCopyOption.REPLACE_EXISTING);}catch(Exception e){throw new IllegalStateException("Cannot save mock VASP state",e);}}
 final Map<String,Long> balances=new HashMap<>(); final Map<String,Map<String,Object>> orders=new HashMap<>(); final Map<String,Map<String,Object>> requests=new HashMap<>();
 Map<String,Object> cached(String id,Map<String,Object> body){if(orders.containsKey(id)&&requests.containsKey(id)&&!requests.get(id).equals(body))throw new org.springframework.web.server.ResponseStatusException(HttpStatus.CONFLICT,"IDEMPOTENCY_CONFLICT");return orders.get(id);}
 Map<String,Object> remember(String id,Map<String,Object> body,Map<String,Object> response){requests.put(id,new LinkedHashMap<>(body));orders.put(id,response);persist();return response;}
 public static void main(String[] args){SpringApplication.run(SimApplication.class,args);}
 void authorize(String supplied){if(!java.security.MessageDigest.isEqual(key.getBytes(),supplied.getBytes()))throw new org.springframework.web.server.ResponseStatusException(HttpStatus.UNAUTHORIZED);}
 long n(Map<String,Object>b,String k){return new BigDecimal(b.get(k).toString()).longValueExact();}
 @GetMapping("/health") Object health(){return Map.of("status","UP","demo",true);}
 @PostMapping("/vasp/portfolio") synchronized Object portfolio(@RequestHeader("X-Api-Key")String k,@RequestBody Map<String,Object>b){authorize(k);String uid=b.get("userId").toString();long balance=balances.computeIfAbsent(uid,x->100_000_000L);return Map.of("asset","USDT","balanceMicro",balance,"btcSats",150_000L,"rate","1.7000","provider","Mock VASP","depositAddress","TKampusDemo"+Math.abs(uid.hashCode())+"TRC20","network","TRC20","demo",true);}
 @PostMapping("/vasp/orders") synchronized Object order(@RequestHeader("X-Api-Key")String k,@RequestBody Map<String,Object>b){authorize(k);String id=Objects.toString(b.getOrDefault("operationId",b.get("orderId"))),uid=b.get("userId").toString();if(cached(id,b)!=null)return cached(id,b);long a=n(b,"amountMicro"),old=balances.computeIfAbsent(uid,x->100_000_000L);if(a<=0)throw new org.springframework.web.server.ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY);boolean buy="BUY".equals(b.get("side"));if(!buy&&old<a)throw new org.springframework.web.server.ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"INSUFFICIENT_CRYPTO");long next=buy?Math.addExact(old,a):old-a;balances.put(uid,next);Map<String,Object> r=Map.of("status","COMPLETED","balanceMicro",next,"orderId",id);return remember(id,b,r);}
 @PostMapping("/vasp/deposit") synchronized Object vaspDeposit(@RequestHeader("X-Api-Key")String k,@RequestBody Map<String,Object>b){authorize(k);String operation=Objects.toString(b.getOrDefault("operationId",UUID.randomUUID().toString()));if(cached(operation,b)!=null)return cached(operation,b);String uid=b.get("userId").toString(),from=Objects.toString(b.get("fromAddress"),"T9yD14Nj9j7xAB4dbGeiX9h8unkKHxuWwb");long a=n(b,"amountMicro");int aml=from.toUpperCase(Locale.ROOT).startsWith("TBLACK")||from.toUpperCase(Locale.ROOT).startsWith("TSANCTION")?92:12;boolean frozen=aml>=80;long old=balances.computeIfAbsent(uid,x->100_000_000L);long next=frozen?old:Math.addExact(old,a);if(!frozen)balances.put(uid,next);String st=frozen?"FROZEN_FOR_AML":"CREDITED";var response=Map.<String,Object>of("status",st,"amlStatus",st,"amlScore",aml,"confirmations",12,"requiredConfirmations",12,"balanceMicro",next,"txHash","0x"+UUID.randomUUID().toString().replace("-",""));return remember(operation,b,response);}
 @PostMapping("/vasp/withdraw") synchronized Object vaspWithdraw(@RequestHeader("X-Api-Key")String k,@RequestBody Map<String,Object>b){authorize(k);String operation=Objects.toString(b.getOrDefault("operationId",UUID.randomUUID().toString()));if(cached(operation,b)!=null)return cached(operation,b);String uid=b.get("userId").toString(),to=Objects.toString(b.getOrDefault("toAddress",b.get("address")),"");long a=n(b,"amountMicro"),old=balances.computeIfAbsent(uid,x->100_000_000L);if(a<=0||old<a)throw new org.springframework.web.server.ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"INSUFFICIENT_CRYPTO");int aml=to.toUpperCase(Locale.ROOT).startsWith("TBLACK")||to.toUpperCase(Locale.ROOT).startsWith("TSANCTION")?95:10;if(aml>=80)return remember(operation,b,Map.of("status","FROZEN_FOR_AML","amlStatus","FROZEN_FOR_AML","amlScore",aml,"balanceMicro",old,"txHash",""));long next=old-a;balances.put(uid,next);var response=Map.<String,Object>of("status","COMPLETED","amlStatus","COMPLETED","amlScore",aml,"balanceMicro",next,"txHash","0x"+UUID.randomUUID().toString().replace("-",""));return remember(operation,b,response);}
 @PostMapping("/registry/lookup") Object registry(@RequestHeader("X-Api-Key")String k,@RequestBody Map<String,Object>b){authorize(k);String fin=Objects.toString(b.get("fin"),"7AZE001").trim().toUpperCase(Locale.ROOT);boolean minor="17YASLI".equals(fin);boolean lowFace="LOWFACE".equals(fin);String birth=minor?"2010-05-10":Objects.toString(b.get("birthDate"),"2003-03-15");if(birth.isBlank())birth="2003-03-15";return Map.of("fin",fin,"maskedName",minor?"C*** M***":"Tələbə İ.", "birthDate",birth,"faceMatchScore",lowFace?0.62:0.96,"registryRef","REG-"+fin,"demo",true);}
 @PostMapping("/liveness/challenge") Object livenessChallenge(@RequestHeader("X-Api-Key")String k){authorize(k);var actions=new ArrayList<>(List.of("TURN_LEFT","TURN_RIGHT","BLINK","SMILE"));Collections.shuffle(actions);return Map.of("challengeId",UUID.randomUUID().toString(),"actions",actions.subList(0,3),"expiresAt",System.currentTimeMillis()+60_000,"demo",true);}
 @PostMapping("/sima/sign") Object simaSign(@RequestHeader("X-Api-Key")String k,@RequestBody Map<String,Object>b){authorize(k);return Map.of("contractId","CNT-"+UUID.randomUUID().toString().substring(0,8),"signatureHash","sima_sha256_"+UUID.randomUUID().toString().replace("-",""),"signedByUser",true,"signedByKampus",true,"provider","Mock SİMA İmza","demo",true);}
 @PostMapping("/cards/reveal") Object revealCard(@RequestHeader("X-Api-Key")String k,@RequestBody Map<String,Object>b){authorize(k);String last4=Objects.toString(b.get("last4"),"2048");return Map.of("pan","416973000000"+last4,"demoPan","4169 7300 0000 "+last4,"expiry","08/29","cvv","842","brand","VISA","expiresAt",System.currentTimeMillis()+60_000,"demo",true);}
 @PostMapping("/lenders/applications") Object offers(@RequestHeader("X-Api-Key")String k,@RequestBody Map<String,Object>b){authorize(k);long a=n(b,"amountMinor");int term=(int)n(b,"termMonths");boolean overdue=Boolean.TRUE.equals(b.get("hasOverdueDebt"));boolean bokt=!overdue&&n(b,"activeMonths")>=2&&a<=150000,bank=!overdue&&n(b,"activeMonths")>=6&&n(b,"averageIncomeMinor")>=30000;return Map.of("offers",List.of(offer("Mock BOKT A",bokt,a,term,28),offer("Mock Bank B",bank,a,term,16)));}
 Map<String,Object> offer(String name,boolean approved,long a,int term,int apr){double r=Math.pow(1+apr/100.0,1.0/12)-1;long monthly=(long)Math.ceil(a*r/(1-Math.pow(1+r,-term)));return Map.of("partner",name,"approved",approved,"aprPercent",apr,"monthlyPaymentMinor",monthly,"totalPayableMinor",monthly*term,"reason",approved?"":"Demo gəlir və aktivlik meyarları ödənmir");}
 @PostMapping({"/bank/topup","/anipay/transfers","/lenders/disburse"}) Object settlement(@RequestHeader("X-Api-Key")String k,@RequestBody Map<String,Object>b){authorize(k);return Map.of("status","COMPLETED","reference",UUID.randomUUID().toString(),"demo",true);}
 @GetMapping(value="/sim/admin",produces=MediaType.TEXT_HTML_VALUE) ResponseEntity<String> simAdmin(){return CardNetwork.html("<span class=\"badge\">KAMPUS-SIM · SANDBOX</span><h1>Xarici Sistem Simulyatoru.</h1><p>Bütün xarici partnyorlar lokal olaraq bu servisdə təqlid olunur:</p><section><strong>Aktiv Mock Servislər</strong><p>✓ Dövlət Reyestri və Üz Tutuşdurma (/registry/lookup)<br>✓ Demo Canlılıq Tapşırıqları (kamera analizi yoxdur) (/liveness/challenge)<br>✓ SİMA İmza Müqavilə Təsdiqi (/sima/sign)<br>✓ Kart Şəbəkəsi · OCT və BIN Tokenizasiya (/card-form/{id})<br>✓ Virtual Kart Emissiyası və Reveal (/cards/reveal)<br>✓ AniPay / AÖS və Partnyor Bank (/anipay/transfers)<br>✓ Mock VASP · USDT, BTC və AML Skrininq (/vasp/*)<br>✓ Mock BOKT A və Mock Bank B (/lenders/*)</p></section>");}
}
